/**
 * System IPC: file dialogs + file IO for import/export, cookie management,
 * diagnostics. Path inputs are always generated by main (dialog results) —
 * the renderer never passes arbitrary paths for reading/writing.
 */
import { app, session, shell, dialog } from 'electron'
import fs from 'node:fs/promises'
import type { BrowserWindow, IpcMain } from 'electron'

const COOKIE_PARTITION = 'postmaster-cookie-store'

export function registerSystemIpc(
  ipcMain: IpcMain,
  getWindow: () => BrowserWindow | null,
): void {
  ipcMain.handle('app:info', () => ({
    version: app.getVersion(),
    electron: process.versions.electron,
    chrome: process.versions.chrome,
    node: process.versions.node,
    platform: process.platform,
  }))

  ipcMain.handle('dialog:importFile', async () => {
    const w = getWindow()
    if (!w) return null
    const result = await dialog.showOpenDialog(w, {
      title: 'Import collection, environment, or OpenAPI file',
      filters: [{ name: 'JSON files', extensions: ['json'] }],
      properties: ['openFile', 'dontAddToRecent'],
    })
    if (result.canceled || result.filePaths.length !== 1) return null
    const file = result.filePaths[0]
    try {
      const content = await fs.readFile(file, 'utf8')
      if (content.length > 26_214_400) return { error: 'File too large (>25 MB)' }
      return { path: file, content }
    } catch (err) {
      return { error: err instanceof Error ? err.message : 'read failed' }
    }
  })

  ipcMain.handle('dialog:exportFile', async (_e, suggestedName: unknown, content: unknown) => {
    const w = getWindow()
    if (!w) return { canceled: true }
    if (typeof suggestedName !== 'string' || suggestedName.length > 240) return { error: 'bad file name' }
    if (typeof content !== 'string' || content.length > 104_857_600) return { error: 'content too large' }
    const result = await dialog.showSaveDialog(w, {
      title: 'Export',
      defaultPath: suggestedName,
      filters: [{ name: 'JSON files', extensions: ['json'] }],
    })
    if (result.canceled || !result.filePath) return { canceled: true }
    try {
      await fs.writeFile(result.filePath, content, 'utf8')
      return { saved: result.filePath }
    } catch (err) {
      return { error: err instanceof Error ? err.message : 'write failed' }
    }
  })

  ipcMain.handle('cookies:list', async () => {
    const ses = session.fromPartition(COOKIE_PARTITION)
    const cookies = await ses.cookies.get({})
    return cookies.map((c) => ({
      domain: c.domain ?? '',
      path: c.path ?? '',
      name: c.name,
      value: c.value,
      expires: c.expirationDate ?? null,
      secure: c.secure,
      httpOnly: c.httpOnly,
    }))
  })

  ipcMain.handle('cookies:clear', async (_e, domain: unknown) => {
    const ses = session.fromPartition(COOKIE_PARTITION)
    if (typeof domain !== 'string') {
      await ses.clearStorageData()
      return true
    }
    const cookies = await ses.cookies.get({ domain })
    for (const c of cookies) {
      const d = c.domain ?? domain
      const host = d.startsWith('.') ? d.slice(1) : d
      const protocol = c.secure ? 'https' : 'http'
      await ses.cookies.remove(`${protocol}://${host}${c.path}`, c.name)
    }
    return true
  })

  ipcMain.handle('shell:openExternal', async (_e, url: unknown) => {
    if (typeof url !== 'string' || !/^https?:\/\//.test(url)) return false
    await shell.openExternal(url)
    return true
  })
}
